  // inspect, so the copy names what could go wrong before it names what could
  // be earned. "Whoever reports this vehicle's sale sets the payout unopposed"
  // is not alarmism; it is what a collection with no verification and no
  // challenge window actually means, and softening it would be the one
  // dishonesty this surface cannot afford.
