  'herd.noIrisTitle': "Pas de module iris sur cet appareil",
  'herd.noIrisBody': "L'appareil photo d'un téléphone est derrière un filtre infrarouge, et l'iris d'un bovin est brun foncé — il n'y a rien à lire en lumière visible. Utilisez la puce ou le numéro.",
  'herd.scopeTitle': "Ce à quoi une capture peut être comparée",
  'herd.scopeBody': "{covered} animaux de ce troupeau ont un gabarit sur cet appareil. {uncovered} n'en ont aucun et ne peuvent pas être comparés : une absence de correspondance ne dit rien à leur sujet.",
  'herd.foundTitle': "Trouvé au registre",
  'herd.foundByTag': "Résolu à partir du code de transpondeur.",
  'herd.foundByNationalId': "Résolu à partir de l'identifiant national.",
  'herd.secondMarkerTitle': "Vérifiez un second marqueur",
  'herd.secondMarkerBody': "Une puce peut être retirée et reposée. Confirmez par le tatouage, la robe ou une biométrie avant d'agir — et si les deux se contredisent, c'est un constat à consigner, pas une erreur à corriger.",
  'herd.openRecord': "Ouvrir la fiche complète",
  'herd.fromReplica': "Lu depuis la copie présente sur cet appareil.",
  'herd.notFoundTitle': "Aucune fiche ne porte cet identifiant",
  'herd.notFoundNational': "Le registre a répondu : rien sur la chaîne ne porte cet identifiant.",
  'herd.notFoundHerd': "Absent de la copie présente sur cet appareil : ce troupeau ne le contient pas. Le registre national n'a pas pu être interrogé — il détient peut-être une fiche pour cet identifiant.",
  'herd.notFoundNext': "Vérifiez les chiffres, puis prévenez un agent. Un animal devant vous dont l'identifiant est inconnu du registre mérite d'être signalé.",
  'herd.matchTitle': "Un animal correspond",
  'herd.matchBody': "Dans ce troupeau, et uniquement face aux gabarits présents sur cet appareil.",
  'herd.runnerUpTitle': "L'autre animal le plus proche",
  'herd.runnerUpBody': "L'animal {id} ressort à une distance de {d}. Il n'atteint pas le seuil opérationnel, mais il en est assez proche pour mériter un regard.",
  'herd.ambiguousTitle': "Deux animaux correspondent. Cela ne se tranche pas ici.",
  'herd.ambiguousBody': "{n} animaux différents atteignent le seuil opérationnel face à cette capture. Des jumeaux font cela. Une capture enregistrée sur le mauvais animal aussi, et une substitution également.",
  'herd.ambiguousNextTitle': "Que faire",
  'herd.ambiguousNextBody': "Ne vous fiez pas à la biométrie. Lisez la puce, vérifiez le tatouage, et s'ils se contredisent faites venir un agent accrédité. La capture est conservée et n'est rattachée à aucun animal.",
  'herd.inconclusiveTitle': "Recommencez la capture",
  'herd.nearThresholdBody': "La meilleure comparaison se situe entre {m} et {i}. Une capture authentique gâchée par la poussière, un mouvement ou une paupière mi-close tombe là, un autre animal aussi. Trente secondes de nouvelle capture tranchent ; un verdict, non.",
  'herd.notComparableBody': "Trop peu des deux gabarits était comparable — moins de {pct} % des bits. Cela dit que la capture est inutilisable, pas que l'animal est différent.",
  'herd.nearMisses': "Les plus proches, pour information seulement :",
  'herd.captureAgainTitle': "Avant de recommencer",
  'herd.captureAgainBody': "Approchez-vous, stabilisez la tête, et gardez le soleil derrière l'animal plutôt que derrière vous.",
  'herd.noCandidateTitle': "Rien dans ce troupeau ne correspond",
  'herd.noCandidateBody': "Comparé à {compared} captures enregistrées.",
  'herd.notComparedTitle': "Et {n} animaux n'ont pas été comparés",
  'herd.notComparedBody': "{n} animaux de ce troupeau n'ont aucun gabarit sur cet appareil. Ils n'ont pas été écartés — ils n'ont pas été examinés.",
  'herd.herdScopeOnly': "Cette recherche a porté sur un seul troupeau. Ce n'est pas une recherche dans le registre national, qui exige une connexion et un service qui n'existe pas encore.",
  'herd.nothingEnrolledTitle': "Rien à quoi comparer",
  'herd.nothingEnrolledBody': "Cet appareil contient {n} animaux et aucun gabarit biométrique.",
  'herd.nothingEnrolledWhy': "Les gabarits ne vont jamais sur la chaîne : ils ne peuvent pas être changés s'ils fuitent, et pour un programme de sélection ils ont une valeur en eux-mêmes. Ils sont enregistrés sur l'appareil, donc un animal doit être capturé une fois avant de pouvoir être reconnu.",
  'herd.noCaptureTitle': "Aucune capture exploitable",
  'herd.refusal.too-blurred': "Trop floue. Approchez-vous et laissez la mise au point se faire.",
  'herd.refusal.too-dark': "Trop sombre. Utilisez l'éclairage.",
  'herd.refusal.eye-not-found': "Aucun œil trouvé dans le cadre.",
  'herd.refusal.moved': "L'animal a bougé pendant la capture.",
  'herd.refusal.cancelled': "Annulée.",
  'herd.unrecognisedTitle': "Ce n'est aucun des deux identifiants",
  'herd.unrecognisedBody': "Rien n'a été demandé au registre. Les deux formes sont :",
  'herd.formNationalId': "l'identifiant national, tiré du certificat",
  'herd.formTag': "le code de transpondeur, 15 chiffres",
  'herd.collisionTitle': "Deux animaux portent le même identifiant sur cet appareil",
  'herd.collisionBody': "Le registre l'interdit : la copie présente sur cet appareil est donc erronée. Téléchargez le troupeau à nouveau avant de vous fier à une recherche.",
  'herd.distance': "Distance",
  'herd.comparedBits': "{pct} % du gabarit comparé",
  'herd.distanceAria': "Distance {d}, pour un seuil opérationnel de {m}",
  'herd.thresholdsCaveat': "Ces seuils viennent de la littérature sur l'iris humain et n'ont pas été recalculés à partir de captures de terrain de cette espèce. C'est un point de départ, pas une réponse.",
  'herd.verdict.match': "Atteint le seuil",
