  'herd.reEnrolDue': "Un animal ne garde pas la même forme. Un gabarit pris il y a trop longtemps cesse de correspondre à la bête à laquelle il appartient, et cet échec ressemble exactement à un registre qui rejette un animal légitime.",
  'herd.templatesStayHereTitle': "Les gabarits ne quittent jamais l'appareil",
  'herd.templatesStayHereBody': "Un gabarit biométrique ne peut pas être changé s'il fuite, et il garde sa valeur toute la vie de l'animal. La chaîne consigne qu'une capture a eu lieu, par qui et quand — jamais la capture elle-même.",
