  'herd.noIrisBody': "Kamera ya simu iko nyuma ya kichujio cha infraredi, na irisi ya ng'ombe ni ya kahawia iliyokolea — hakuna cha kusoma katika mwanga wa kawaida. Tumia transponda au namba badala yake.",
  'herd.scopeTitle': "Kile kipimo kinachoweza kulinganishwa nacho",
  'herd.scopeBody': "Wanyama {covered} wa kundi hili wana kigezo kwenye kifaa hiki. Wanyama {uncovered} hawana hata kimoja na hawawezi kulinganishwa kabisa — kukosa kulingana hakusemi lolote kuwahusu.",
  'herd.foundTitle': "Amepatikana kwenye daftari",
  'herd.foundByTag': "Amepatikana kutoka msimbo wa transponda.",
  'herd.foundByNationalId': "Amepatikana kutoka kitambulisho cha kitaifa.",
  'herd.secondMarkerTitle': "Kagua alama ya pili",
  'herd.secondMarkerBody': "Transponda inaweza kutolewa na kuwekwa tena. Thibitisha kwa tatuu, kwa manyoya au kwa kipimo cha kibaiolojia kabla hujachukua hatua — na kama hizo mbili zinapingana, hilo ni jambo la kuandikisha, si kosa la kusahihisha.",
  'herd.openRecord': "Fungua rekodi kamili",
  'herd.fromReplica': "Imesomwa kutoka nakala iliyo kwenye kifaa hiki.",
  'herd.notFoundTitle': "Hakuna rekodi inayobeba hiki",
  'herd.notFoundNational': "Daftari limejibu: hakuna kitu kwenye mnyororo kinachobeba kitambulisho hiki.",
  'herd.notFoundHerd': "Haiko kwenye nakala iliyo kwenye kifaa hiki, kwa hivyo kundi hili halina mnyama huyu. Daftari la kitaifa halikuweza kuulizwa — huenda lina rekodi ya kitambulisho hiki.",
  'herd.notFoundNext': "Kagua tarakimu, kisha mwambie afisa. Mnyama aliye mbele yako mwenye kitambulisho ambacho daftari halijawahi kukiona anastahili kuripotiwa.",
  'herd.matchTitle': "Mnyama mmoja amelingana",
  'herd.matchBody': "Ndani ya kundi hili, na dhidi ya vigezo vilivyo kwenye kifaa hiki pekee.",
  'herd.runnerUpTitle': "Mnyama mwingine aliye karibu zaidi",
  'herd.runnerUpBody': "Mnyama {id} amerudi kwa umbali wa {d}. Hajafikia kizingiti cha utendaji, lakini yuko karibu vya kutosha kustahili kuangaliwa.",
  'herd.ambiguousTitle': "Wanyama wawili wamelingana. Hili haliamuliwi hapa.",
  'herd.ambiguousBody': "Wanyama {n} tofauti wamefikia kizingiti cha utendaji dhidi ya kipimo hiki. Mapacha hufanya hivyo. Kipimo kilichoandikishwa kwa mnyama asiye sahihi pia, na kubadilishwa kwa mnyama pia.",
  'herd.ambiguousNextTitle': "La kufanya",
  'herd.ambiguousNextBody': "Usiendelee kwa kutegemea kipimo cha kibaiolojia. Soma transponda, kagua tatuu, na kama vinapingana mlete wakala aliyeidhinishwa. Kipimo kimehifadhiwa na hakijaunganishwa na mnyama yeyote.",
  'herd.inconclusiveTitle': "Rudia kipimo",
  'herd.nearThresholdBody': "Ulinganisho bora umeangukia kati ya {m} na {i}. Kipimo halisi kilichoharibiwa na vumbi, mwendo au kope lililofumba nusu huangukia hapo, na mnyama mwingine pia. Sekunde thelathini za kupima upya hulimaliza; hukumu hailimalizi.",
  'herd.notComparableBody': "Sehemu ndogo mno ya vigezo viwili iliweza kulinganishwa — chini ya asilimia {pct} ya biti. Hii inasema kipimo hakifai, si kwamba mnyama ni mwingine.",
  'herd.nearMisses': "Vilivyokaribia zaidi, kwa habari tu:",
  'herd.captureAgainTitle': "Kabla ya kujaribu tena",
  'herd.captureAgainBody': "Sogea karibu zaidi, tuliza kichwa, na weka jua nyuma ya mnyama badala ya nyuma yako.",
  'herd.noCandidateTitle': "Hakuna kilicholingana katika kundi hili",
  'herd.noCandidateBody': "Imelinganishwa na vipimo {compared} vilivyoandikishwa.",
  'herd.notComparedTitle': "Na wanyama {n} hawakulinganishwa",
  'herd.notComparedBody': "Wanyama {n} wa kundi hili hawana kigezo kwenye kifaa hiki. Hawakuondolewa — hawakuangaliwa.",
  'herd.herdScopeOnly': "Utafutaji huu umehusu kundi moja tu. Si utafutaji katika daftari la kitaifa, ambao unahitaji muunganisho na huduma ambayo bado haipo.",
  'herd.nothingEnrolledTitle': "Hakuna cha kulinganisha nacho",
  'herd.nothingEnrolledBody': "Kifaa hiki kina wanyama {n} na hakina vigezo vya kibaiolojia hata kimoja.",
  'herd.nothingEnrolledWhy': "Vigezo havipandi kwenye mnyororo kamwe — haviwezi kubadilishwa vikivuja, na kwa mpango wa uzalishaji vina thamani vyenyewe. Vinaandikishwa kwenye kifaa, kwa hivyo mnyama ni lazima anaswe mara moja kabla ya kuweza kutambuliwa.",
  'herd.noCaptureTitle': "Hakuna kipimo kinachofaa",
